// v1.0 - Level one subcontractor quote against the bid package scope checklist
// Computes revision, scope gaps, plug total (allowances for missing scope) and leveled price.
const ai = $('Read, Match and Scope-Check Quote').first().json.output;
const pkg = $('Get Matched Bid Package').first().json;
const email = $('Loop Over Quote Emails').first().json;
const settings = $('Quote Intake Settings').first().json;
const existing = $input.all().map(i => i.json).find(r => r.id && r.sub_email);

const toNumber = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const senderEmail = String(email.from?.value?.[0]?.address || '').toLowerCase();
const subEmail = String(ai.sub_contact_email || senderEmail).trim().toLowerCase();

// scope_checklist format: "Item=allowance; Item=allowance"
const checklist = String(pkg.scope_checklist || '')
  .split(';')
  .map(s => s.trim())
  .filter(Boolean)
  .map(entry => {
    const idx = entry.lastIndexOf('=');
    return {
      item: (idx > -1 ? entry.slice(0, idx) : entry).trim(),
      allowance: idx > -1 ? toNumber(entry.slice(idx + 1)) : toNumber(settings.default_plug_amount),
    };
  });

const coverage = Array.isArray(ai.scope_coverage) ? ai.scope_coverage : [];
const gaps = checklist
  .map(({ item, allowance }) => {
    const key = norm(item);
    const hit = coverage.find(c => norm(c.item) === key)
      || coverage.find(c => norm(c.item) && (norm(c.item).includes(key) || key.includes(norm(c.item))));
    return { item, allowance, status: hit ? String(hit.status).toLowerCase() : 'not_mentioned' };
  })
  .filter(g => g.status !== 'included');

const basePrice = toNumber(ai.base_price);
const plugTotal = gaps.reduce((sum, g) => sum + g.allowance, 0);
const money = n => '$' + Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 0 });
const label = s => s.replace('_', ' ');

// A new quote from the same sub is the next revision; re-running the same email keeps its number
const revision = !existing ? 1
  : existing.gmail_message_id === email.id ? Number(existing.revision) || 1
  : (Number(existing.revision) || 1) + 1;

return [{
  json: {
    package_code: pkg.package_code,
    project_name: pkg.project_name,
    trade: pkg.trade,
    sub_company: ai.sub_company || email.from?.value?.[0]?.name || subEmail,
    sub_email: subEmail,
    revision,
    base_price: basePrice,
    inclusions: ai.inclusions || '',
    exclusions: ai.exclusions || '',
    qualifications: ai.qualifications || '',
    alternates: ai.alternates || '',
    validity_date: ai.validity_date || '',
    addenda_acknowledged: ai.addenda_acknowledged || '',
    scope_gaps: gaps.map(g => g.item + ' (' + label(g.status) + ', plug ' + money(g.allowance) + ')').join('; '),
    gap_count: gaps.length,
    gap_list: gaps.map(g => '- ' + g.item + ' (' + label(g.status) + ')').join('\n'),
    plug_total: plugTotal,
    leveled_price: basePrice + plugTotal,
    quote_status: 'active',
    gmail_message_id: email.id,
    received_at: new Date().toISOString(),
  },
}];

