// v1.0 - Decide the sweep action for one bid package and build its leveling sheet
// stage: chase (remind missing bidders), close (bidding closed, get award approval), no_bids, or wait
const pkg = $('Loop Over Bid Packages').first().json;
const settings = $('Sweep Settings').first().json;
const quotes = $input.all().map(i => i.json).filter(q => q.id && q.sub_email);

const due = DateTime.fromISO(String(pkg.bid_due_date).slice(0, 10), { zone: $today.zone });
const daysToDue = Math.round(due.diff($today, 'days').days);
const chaseDays = Number(settings.chase_days_before_due) || 2;

const invited = String(pkg.invited_subs || '').split(',').map(e => e.trim().toLowerCase()).filter(Boolean);
const quoted = new Set(quotes.map(q => String(q.sub_email).toLowerCase()));
const missing = invited.filter(e => !quoted.has(e));

// 'closing' is set by the Close Bidding node once the due date has passed
let stage = 'wait';
if (pkg.status === 'closing') stage = quotes.length ? 'close' : 'no_bids';
else if ((daysToDue === chaseDays || daysToDue === 0) && missing.length) stage = 'chase';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = n => '$' + Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 0 });
const ranked = [...quotes].sort((a, b) => (Number(a.leveled_price) || 0) - (Number(b.leveled_price) || 0));
const best = ranked[0];

const rows = ranked.map((q, i) =>
  '<tr' + (i === 0 ? ' style=background:#e8f5e9' : '') + '><td>' + esc(q.sub_company) + '</td><td>' + esc(q.revision) + '</td><td>' + money(q.base_price) + '</td><td>' + money(q.plug_total) + '</td><td><b>' + money(q.leveled_price) + '</b></td><td>' + esc(q.scope_gaps || 'None') + '</td><td>' + esc(q.validity_date || '-') + '</td><td>' + esc(q.addenda_acknowledged || '-') + '</td></tr>'
).join('');
const levelingHtml = '<table border=1 cellpadding=6 cellspacing=0 style=border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px><tr style=background:#263238;color:#ffffff><th>Subcontractor</th><th>Rev</th><th>Base bid</th><th>Plugs</th><th>Leveled total</th><th>Scope gaps</th><th>Valid until</th><th>Addenda</th></tr>' + rows + '</table>';
const levelingText = ranked.map((q, i) =>
  (i + 1) + '. ' + q.sub_company + ' (rev ' + q.revision + '): base ' + money(q.base_price) + ', plugs ' + money(q.plug_total) + ', leveled ' + money(q.leveled_price) + '. Gaps: ' + (q.scope_gaps || 'none') + '. Exclusions: ' + (q.exclusions || 'none') + '. Qualifications: ' + (q.qualifications || 'none') + '. Alternates: ' + (q.alternates || 'none') + '. Valid until: ' + (q.validity_date || 'n/a') + '. Addenda: ' + (q.addenda_acknowledged || 'n/a') + '.'
).join('\n');

return [{
  json: {
    package_code: pkg.package_code,
    project_name: pkg.project_name,
    trade: pkg.trade,
    estimator_email: pkg.estimator_email,
    bid_due_date: pkg.bid_due_date,
    days_to_due: daysToDue,
    stage,
    quote_count: quotes.length,
    invited_count: invited.length,
    missing_subs: missing,
    leveling_html: levelingHtml,
    leveling_text: levelingText,
    recommended_sub_company: best ? best.sub_company : '',
    recommended_sub_email: best ? best.sub_email : '',
    recommended_leveled_price: best ? Number(best.leveled_price) || 0 : 0,
    unsuccessful_subs: ranked.slice(1).map(q => ({ sub_company: q.sub_company, sub_email: q.sub_email })),
  },
}];
